# Instalador de "Codigos" para la mini app de Chivato.
# No toca bot.py. Crea un servicio aparte en el puerto 8766.
import base64, os, re, shutil, subprocess, sys, time, urllib.request

DIR = "/opt/chivato/codigos"
INDEX = "/opt/chivato/miniapp/index.html"
CADDY = "/etc/caddy/Caddyfile"
HOST = "chivato-ofertas.duckdns.org"
SERVER_PY = ""
PAGINA = ""

def paso(t):
    print("\n== " + t, flush=True)

def sh(cmd):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True)

sello = time.strftime("%Y%m%d-%H%M%S")

paso("1/5 Archivos")
os.makedirs(DIR, exist_ok=True)
open(os.path.join(DIR, "server.py"), "wb").write(base64.b64decode(SERVER_PY))
open(os.path.join(DIR, "codigos.html"), "wb").write(base64.b64decode(PAGINA))
print("ok:", DIR, "(datos.json se conserva si ya existia)")

paso("2/5 Servicio chivato-codigos")
open("/etc/systemd/system/chivato-codigos.service", "w").write("""[Unit]
Description=Chivato - codigos de descuento
After=network-online.target

[Service]
WorkingDirectory=%s
ExecStart=/usr/bin/python3 %s/server.py
Restart=always
RestartSec=5

[Install]
WantedBy=multi-user.target
""" % (DIR, DIR))
sh("systemctl daemon-reload && systemctl enable chivato-codigos >/dev/null 2>&1; systemctl restart chivato-codigos")
time.sleep(3)
print(sh("journalctl -u chivato-codigos -n 3 --no-pager -o cat").stdout.strip())

paso("3/5 Caddy")
caddy = open(CADDY, encoding="utf-8").read()
if "127.0.0.1:8766" in caddy:
    print("ya estaba configurado")
else:
    m = re.search(r"^[^\n#]*" + re.escape(HOST) + r"[^\n]*\{[ \t]*\n", caddy, re.M)
    if not m:
        print("ERROR: no encuentro el bloque de %s en %s. No toco Caddy." % (HOST, CADDY))
        sys.exit(1)
    nuevo = caddy[:m.end()] + "    reverse_proxy /codigos* 127.0.0.1:8766\n    reverse_proxy /api/codigos* 127.0.0.1:8766\n" + caddy[m.end():]
    shutil.copy(CADDY, CADDY + ".bak-" + sello)
    open(CADDY, "w", encoding="utf-8").write(nuevo)
    v = sh("caddy validate --config %s --adapter caddyfile" % CADDY)
    if v.returncode != 0:
        shutil.copy(CADDY + ".bak-" + sello, CADDY)
        print("ERROR: Caddy no acepta el cambio, lo he deshecho.\n" + v.stderr[-600:])
        sys.exit(1)
    sh("systemctl reload caddy")
    print("ok (copia en %s.bak-%s)" % (CADDY, sello))

paso("4/5 Boton Codigos en la mini app")
if not os.path.exists(INDEX):
    print("AVISO: no existe", INDEX, "- la pagina /codigos funciona igual")
else:
    h = open(INDEX, encoding="utf-8").read()
    if "CODIGOS-BTN" in h:
        print("ya estaba")
    else:
        boton = ('\n<!-- CODIGOS-BTN -->\n<a href="/codigos" id="codigos-btn" aria-label="Códigos de descuento" '
                 'style="position:fixed;right:14px;bottom:calc(92px + env(safe-area-inset-bottom));z-index:9999;'
                 'display:flex;align-items:center;gap:6px;min-height:44px;padding:0 16px;border-radius:999px;'
                 'background:#e7a35c;color:#1c120b;font:700 14px DM Sans,system-ui,sans-serif;text-decoration:none;'
                 'box-shadow:0 6px 18px rgba(0,0,0,.35)">'
                 '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
                 'stroke-linejoin="round" aria-hidden="true"><path d="M3 9V6a1 1 0 0 1 1-1h16a1 1 0 0 1 1 1v3a3 3 0 0 0 0 6v3'
                 'a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1v-3a3 3 0 0 0 0-6z"/></svg>Códigos</a>\n')
        shutil.copy(INDEX, INDEX + ".bak-" + sello)
        i = h.lower().rfind("</body>")
        h = h[:i] + boton + h[i:] if i >= 0 else h + boton
        open(INDEX, "w", encoding="utf-8").write(h)
        print("ok (copia en %s.bak-%s)" % (INDEX, sello))

paso("5/5 Comprobacion")
ok = True
for url in ("http://127.0.0.1:8766/api/codigos", "https://%s/api/codigos" % HOST):
    try:
        r = urllib.request.urlopen(url, timeout=15).read(80)
        print("OK  ", url, r.decode(errors="replace"))
    except Exception as e:
        ok = False
        print("FALLA", url, e)
arr = sh("journalctl -u chivato-codigos -n 20 --no-pager -o cat | grep 'Codigos en' | tail -1").stdout.strip()
print(arr)
if "admins=0" in arr:
    print("\nAVISO: no encuentro tu ID de administrador en .env.\n"
          "Ejecuta (con tu ID de Telegram):  echo 'CODIGOS_ADMIN=TU_ID' >> /opt/chivato/.env && systemctl restart chivato-codigos")
if "tokens=0" in arr:
    print("\nAVISO: no encuentro el token del bot en .env")
print("\nLISTO" if ok else "\nHAY ALGUN FALLO: manda captura")
